//Lots of code inspiration from iq, FrabiceNeyret, and many awesome people here.
#define RENDERTIME 300  
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    vec3 col = vec3(0.0);
    if(iFrame<RENDERTIME)
    {
        //Progress bar
        vec2 uv = fragCoord.xy / iResolution.xy;
        float mask = step(0.1,uv.x)*step(uv.x,0.9);
        mask *= step(0.1,uv.y)*step(uv.y,0.15);
        mask *= step(uv.x,0.1+0.8*float(iFrame)/float(RENDERTIME));
        col+=vec3(1.0)*mask;

    }
    else
    {
        //Final render
        col = texture(iChannel0,fragCoord.xy/iResolution.xy).rgb/float(iFrame);
        col = pow( clamp(col,0.0,1.0), vec3(0.9) );
    }

    fragColor = vec4( col, 1.0 );
}

uint base_hash(uvec2 p) {
    p = 1103515245U*((p >> 1U)^(p.yx));
    uint h32 = 1103515245U*((p.x)^(p.y>>3U));
    return h32^(h32 >> 16);
}

float g_seed = 0.;

float hash1(inout float seed) {
    uint n = base_hash(floatBitsToUint(vec2(seed+=.1,seed+=.1)));
    return float(n)/float(0xffffffffU);
}

vec2 hash2(inout float seed) {
    uint n = base_hash(floatBitsToUint(vec2(seed+=.1,seed+=.1)));
    uvec2 rz = uvec2(n, n*48271U);
    return vec2(rz.xy & uvec2(0x7fffffffU))/float(0x7fffffff);
}

vec3 hash3(inout float seed) {
    uint n = base_hash(floatBitsToUint(vec2(seed+=.1,seed+=.1)));
    uvec3 rz = uvec3(n, n*16807U, n*48271U);
    return vec3(rz & uvec3(0x7fffffffU))/float(0x7fffffff);
}

mat2 rot(float a){
    return mat2(cos(a),sin(a),-sin(a),cos(a));
}

vec3 hsv2rgb( in vec3 c )
{
    vec3 rgb = clamp( abs(mod(c.x*6.0+vec3(0.0,4.0,2.0),6.0)-3.0)-1.0, 0.0, 1.0 );
	return c.z * mix( vec3(1.0), rgb, c.y);
}

float sdBox( vec3 p, vec3 b )
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

float sdBoxFrame( vec3 p, vec3 b, float e )
{
       p = abs(p  )-b;
  vec3 q = abs(p+e)-e;
  return min(min(
      length(max(vec3(p.x,q.y,q.z),0.0))+min(max(p.x,max(q.y,q.z)),0.0),
      length(max(vec3(q.x,p.y,q.z),0.0))+min(max(q.x,max(p.y,q.z)),0.0)),
      length(max(vec3(q.x,q.y,p.z),0.0))+min(max(q.x,max(q.y,p.z)),0.0));
}

//Scene SDF, just a bunch of spheres and a plane
vec2 map(vec3 p)
{
    vec2 res = vec2(1000.0,-1.0);
    float f;  
    vec3 pp = p;

    pp = p + vec3(0.0,0.5,0.0);
    f = sdBox(pp,vec3(2.5,0.1,5.0));
    if(f < res.x) res = vec2(f,2.0);

    pp = p + vec3(0.0,-2.4,1.5);
    f = sdBox(pp,vec3(2.5,0.1,5.0));
    if(f < res.x) res = vec2(f,2.0);

    pp = p + vec3(2.5,0.0,0.0);
    f = sdBox(pp,vec3(0.1,2.5,5.0));
    if(f < res.x) res = vec2(f,2.0);

    pp = p + vec3(-2.5,0.0,0.0);
    f = sdBox(pp,vec3(0.1,2.5,5.0));
    if(f < res.x) res = vec2(f,2.0);

    pp = p + vec3(0.0,0.0,-5.0);
    f = sdBox(pp,vec3(3.0,2.5,0.1));
    if(f < res.x) res = vec2(f,2.0);

    pp = p + vec3(0.0,0.0,5.0);
    f = sdBox(pp,vec3(3.0,2.5,0.1));
    if(f < res.x) res = vec2(f,2.0);

    for(int i=0;i<8;i++)
    {
        float angle = 2.0*3.14159*float(i)/(float(8.0)-1.0);
        pp = p;
        pp += 0.75 * vec3(cos(angle),sin(angle)-1.0,-3.0+1.0*cos(3.0*angle));
        f = length(pp)-0.1*float(i);
        if(f < res.x) res = vec2(f,3.0);
    }

    return res;
}

//Normal SDF computation
vec3 normal( vec3 pos )
{
    const vec2 eps = vec2(0.0001,0.0);
    return normalize( vec3(
      map( pos+eps.xyy ).x - map( pos-eps.xyy ).x,
      map( pos+eps.yxy ).x - map( pos-eps.yxy ).x,
      map( pos+eps.yyx ).x - map( pos-eps.yyx ).x ) );
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //Seed for global noise
    g_seed = float(base_hash(floatBitsToUint(fragCoord)))/float(0xffffffffU)+10.0*iTime;

    vec2 uv = fragCoord.xy / iResolution.xy - 0.5;
    uv.x *= iResolution.x / iResolution.y;

    //Bit of camera jittering to avoid some artifacts
    uv+=0.002*(hash2(g_seed)-0.5);    
    vec3 ro = vec3( uv, 0.0 );
    vec3 rd = normalize( vec3( uv, 1.0 ) );

    //Camera setup
    ro.z-=2.0;
    ro.y-=-0.5;

    ro.yz *= rot(-0.1);
    rd.yz *= rot(-0.1);
    ro.xz *= rot(0.2);
    rd.xz *= rot(0.2);

    //Long exposure effect
    ro.xz *= rot(0.08*sin(1.0*iTime)*smoothstep(0.2,0.75,length(uv)));
    rd.xy *= rot(0.08*sin(1.2*iTime)*smoothstep(0.2,0.75,length(uv)));

    //Directional light
    vec3 ldir = normalize(vec3(0.0,1.0,1.0));

    //Initialize final color for this pass
    vec3 col = vec3(0.0,0.0,0.0);

    //Each time we simulate a color. Useful for any refraction thing.
    float rand = hash1(g_seed);
    vec3 colmask = hsv2rgb(vec3(rand,1.0,8.0));

    //More path tracer variables
    float mask = 1.0;
    float bounces = 0.0;
    float maxscreenbounces = 20.0;

    //Asymmetric bounce count. More likely the contribution of direct lighting.
    float maxbounces = floor(maxscreenbounces*exp(-6.0*hash1(g_seed)));

    float i = 0.0;
    float maxit = 128.0;

    for(; i<maxit; i+=1.0)
    {  
        vec2 res = map(ro);
        if(abs(res.x)<0.0001)
        {

            vec3 nor = normal(ro);
            ro += 0.01*nor;

            if(res.y==2.0)
            {
                float tile = smoothstep(-0.001,0.001,sin(5.0*ro.x)*sin(5.0*ro.z)*sin(5.0*ro.y));
                vec3 rd1 = normalize( hash3(g_seed)-0.5 );
                rd1 *= sign(dot(rd1,nor));
                rd = normalize(reflect(rd+0.0*normalize(hash3(g_seed)-0.5),nor));                
                rd = normalize(mix(rd,rd1,0.0+0.5*tile));      
                colmask *= (0.8+0.2*tile);
            }

            if(res.y==3.0)
            {
                if(res.x>0.0 && hash1(g_seed)>0.7)
                {
                    rd = reflect(rd,nor);
                }
                else
                {
                    float ior = 1.0+4.0*(rand)+3.0;
                    float ind = mix(ior,1.0/ior,step(0.0,res.x));
                    rd = refract(rd,nor*sign(res.x),ind); 
                    ro-=0.03*nor*sign(res.x);
                }

                colmask *= 1.5*vec3(1.0,0.5,0.1);
            }


            if(bounces==maxbounces) rd = normalize(ldir+0.1*(hash3(g_seed)-0.5));
            mask*=max(1.0,dot(rd,nor));

            if(bounces>maxbounces)
            {
                mask*=0.0;
                break;
            }

            bounces += 1.0;
        }

        if(ro.y>10.0) break;
        ro += abs(res.x) * rd;
    }


    if(i>maxit-1.0) mask*=0.0;

    col = mask * colmask;
    col += texture(iChannel0,fragCoord.xy / iResolution.xy).rgb;
    fragColor = vec4(col,0.0);
}
